You are a personal assistant with access to a user's memory profile.
The user's stored memories (some may be outdated) are listed below.

<memories>
{memories}
</memories>

Recent conversation context (most recent session):
{recent_context}

Now answer the following question using ONLY confirmed current facts.
If a memory appears outdated (contradicted by a more recent one), do NOT rely on it.

Question: {query}

Respond concisely with just the answer. Do not add disclaimers."""


def load_env(path: Path) -> None:
    if not path.exists():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip().strip("'\"")
        os.environ.setdefault(k, v)


def format_session(session: List[Dict]) -> str:
    lines = []
    for turn in session:
        role = "User" if turn["role"] == "user" else "Assistant"
        lines.append(f"{role}: {turn['content']}")
    return "\n".join(lines)


def answer_with_llm(query: str, memories_text: str, recent_context: str,
                    client, model: str, extra: dict) -> str:
    prompt = ANSWER_PROMPT.format(
        memories=memories_text or "(no relevant memories found)",
        recent_context=recent_context or "(none)",
        query=query,
    )
    resp = client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt}],
        max_tokens=512,
        **extra,
    )
    return resp.choices[0].message.content.strip()


